{"content": "import { promises as fs } from "node:fs";
import { dirname, join } from "node:path";
import { randomUUID } from "node:crypto";

const DATA_DIR = join(process.cwd(), "data");
const DATA_FILE = join(DATA_DIR, "books.json");

async function ensureFile() {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, "[]", "utf8");
  }
}

/** @returns {Promise<import('./types').Book[]>} */
export async function readBooks() {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * @param {import('./types').Book[]} books
 */
async function writeBooks(books) {
  await ensureFile();
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), "utf8");
}

/**
 * @param {{ title: string, author: string, notes?: string }} input
 * @returns {Promise<import('./types').Book>}
 */
export async function addBook({ title, author, notes }) {
  const books = await readBooks();
  /** @type {import('./types').Book} */
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    status: "reading",
    notes: (notes ?? "").trim(),
    addedAt: new Date().toISOString(),
  };
  books.push(book);
  await writeBooks(books);
  return book;
}

/**
 * @param {string} id
 * @returns {Promise<import('./types').Book|null>}
 */
export async function getBook(id) {
  const books = await readBooks();
  return books.find((b) => b.id === id) ?? null;
}

/**
 * @param {string} id
 * @param {{ status?: 'reading'|'finished', notes?: string }} patch
 * @returns {Promise<import('./types').Book|null>}
 */
export async function updateBook(id, patch) {
  const books = await readBooks();
  const idx = books.findIndex((b) => b.id === id);
  if (idx === -1) return null;
  const book = books[idx];
  if (patch.status) {
    book.status = patch.status;
    book.finishedAt = patch.status === "finished" ? new Date().toISOString() : null;
  }
  if (typeof patch.notes === "string") {
    book.notes = patch.notes.trim();
  }
  books[idx] = book;
  await writeBooks(books);
  return book;
}
