import { useState } from "react";

export default function AddBookForm() {
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [notes, setNotes] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function submit(e) {
    e.preventDefault();
    if (!title.trim() || !author.trim()) {
      setError("Title and author are required.");
      return;
    }
    setBusy(true);
    setError("");
    const res = await fetch("/api/books", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, author, notes }),
    });
    setBusy(false);
    if (!res.ok) {
      setError("Could not save the book. Try again.");
      return;
    }
    setTitle("");
    setAuthor("");
    setNotes("");
    // Re-render server data: refresh the page so the new book shows up.
    window.location.reload();
  }

  return (
    <form className="add" onSubmit={submit}>
      <div className="row">
        <label>
          Title
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="The Name of the Wind"
            disabled={busy}
            autoFocus
          />
        </label>
        <label>
          Author
          <input
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            placeholder="Patrick Rothfuss"
            disabled={busy}
          />
        </label>
      </div>
      <label>
        Notes (optional)
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="First impressions, quotes, why I picked it up…"
          disabled={busy}
        />
      </label>
      {error ? <div style={{ color: "#b3261e", fontSize: 14 }}>{error}</div> : null}
      <div className="actions">
        <button type="submit" className="primary" disabled={busy}>
          {busy ? "Adding…" : "Add book"}
        </button>
      </div>
    </form>
  );
}
