  const [status, setStatus] = useState(book.status);
  const [savingNotes, setSavingNotes] = useState(false);
  const [toggling, setToggling] = useState(false);
  const [copied, setCopied] = useState(false);
  const [msg, setMsg] = useState("");

  async function saveNotes(e) {
    e.preventDefault();
    setSavingNotes(true);
    setMsg("");
    const res = await fetch(`/api/books/${book.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ notes }),
    });
    setSavingNotes(false);
    setMsg(res.ok ? "Notes saved." : "Could not save notes.");
  }

  async function toggleStatus() {
    const next = status === "finished" ? "reading" : "finished";
    setToggling(true);
    setMsg("");
    const res = await fetch(`/api/books/${book.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: next }),
    });
    setToggling(false);
    if (res.ok) {
      setStatus(next);
    } else {
      setMsg("Could not update status.");
    }
  }

  async function copyLink() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Clipboard may be unavailable; the input still lets the user copy manually.
    }
  }

  return (
    <>
      <div className="status-row">
        <span className={`badge ${status}`}>{status}</span>
        <button onClick={toggleStatus} disabled={toggling} className="primary">
          {toggling
            ? "Updating…"
            : status === "finished"
            ? "Mark as reading"
            : "Mark as finished"}
        </button>
      </div>

      <h3>Notes</h3>
      <form onSubmit={saveNotes}>
        <textarea
          className="notes"
          style={{
            width: "100%",
            font: "inherit",
            padding: "10px",
            border: "1px solid var(--line)",
            borderRadius: 8,
            background: "var(--bg)",
            minHeight: 120,
            resize: "vertical",
          }}
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Write your notes about this book…"
        />
        <div style={{ marginTop: 10, display: "flex", gap: 10, alignItems: "center" }}>
          <button type="submit" disabled={savingNotes}>
            {savingNotes ? "Saving…" : "Save notes"}
          </button>
          {msg ? <span style={{ fontSize: 14, color: "var(--muted)" }}>{msg}</span> : null}
        </div>
      </form>

      <div className="share">
        <h3 style={{ margin: 0 }}>Share this book</h3>
        <input readOnly value={typeof window !== "undefined" ? window.location.href : ""} onFocus={(e) => e.target.select()} />
        <button type="button" onClick={copyLink}>
          {copied ? "Copied!" : "Copy link"}
        </button>
      </div>
    </>
  );
}

