  if (Object.keys(patch).length === 0) {
    return NextResponse.json(
      { error: "Nothing to update. Send 'status' or 'notes'." },
      { status: 400 }
    );
  }

  const book = await updateBook(id, patch);
  if (!book) {
    return NextResponse.json({ error: "Book not found." }, { status: 404 });
